class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.1/commando_0.10.1_darwin_arm64.tar.gz"
      sha256 "d519bc7fd9e390a29df80f1cfe4fc412f1757192ef82644a94c4e6982335ed48"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.1/commando_0.10.1_darwin_amd64.tar.gz"
      sha256 "27a5091433114d59230e2fd8567f70352db842302fd1083ab6d894e2e644f8fc"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.1/commando_0.10.1_linux_arm64.tar.gz"
      sha256 "b14df6478345e2e27aa779f6299b9b936cd9d19a2e9e08b92710ef86ed595e42"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.1/commando_0.10.1_linux_amd64.tar.gz"
      sha256 "35dc3cb1c96222d1cfdd96f0e429a316748821bdf0e481a966bc53548b32ec5c"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
